def check_time_limit(m, n, t):
    # Define the number of operations for each algorithm type
    if t == 1:
        operations = n!
    elif t == 2:
        operations = 2 ** n
    elif t == 3:
        operations = n ** 4
    elif t == 4:
        operations = n ** 3
    elif t == 5:
        operations = n ** 2
    elif t == 6:
        operations = n * (n.bit_length() - 1)  # Approximation of n log n
    elif t == 7:
        operations = n
    else:
        return "TLE"  # Invalid algorithm type

    # Compare the calculated operations with m
    if operations <= m:
        return "AC"
    else:
        return "TLE"

# Read input
m, n, t = map(int, input().split())

# Output the result
print(check_time_limit(m, n, t))
